"""Recurring transaction detection on synthetic ledgers generated by code.

Payees, amounts and dates are invented; each ledger is built from a pattern
(cadence, amount, jitter) so the expected answer is known.
"""

from __future__ import annotations

import random
import uuid
from collections.abc import Iterable
from datetime import date, timedelta
from decimal import Decimal

from app.domain.recurring import detection
from app.domain.recurring.detection import Observed, Pattern
from app.domain.reports.dates import add_months
from app.domain.transactions.models import Cadence

TODAY = date(2026, 6, 30)
D = Decimal
ACCOUNT = uuid.UUID("00000000-0000-7000-8000-000000000001")
OTHER_ACCOUNT = uuid.UUID("00000000-0000-7000-8000-000000000002")


def rows(
    days: Iterable[date],
    amounts: Iterable[Decimal | str] | Decimal | str,
    *,
    payee: str = "Synthetic Payee",
    payee_id: uuid.UUID | None = None,
    account: uuid.UUID = ACCOUNT,
    category: uuid.UUID | None = None,
) -> list[Observed]:
    day_list = list(days)
    if isinstance(amounts, (Decimal, str)):
        values = [D(str(amounts))] * len(day_list)
    else:
        values = [D(str(a)) for a in amounts]
    return [
        Observed(uuid.uuid4(), account, d, v, payee_id, payee, category)
        for d, v in zip(day_list, values, strict=True)
    ]


def monthly(first: date, count: int) -> list[date]:
    return [add_months(first, i) for i in range(count)]


def every(first: date, step: int, until: date = TODAY) -> list[date]:
    out = []
    day = first
    while day <= until:
        out.append(day)
        day += timedelta(days=step)
    return out


def only(found: list[detection.Candidate]) -> detection.Candidate:
    assert len(found) == 1, found
    return found[0]


def test_monthly_subscription_with_text_variants() -> None:
    days = monthly(date(2025, 7, 5), 12)
    texts = [f"STREAMFLIX #{1000 + i}" if i % 2 else f"Streamflix {i}*" for i in range(12)]
    ledger = [
        Observed(uuid.uuid4(), ACCOUNT, d, D("-15.99"), None, t, None)
        for d, t in zip(days, texts, strict=True)
    ]
    found = only(detection.detect(ledger, TODAY))
    assert found.pattern is Pattern.MONTHLY
    assert (found.cadence, found.interval_count) == (Cadence.MONTHLY, 1)
    assert found.amount_min == found.amount_max == D("-15.99")
    assert found.payee_key == "text:streamflix"
    assert found.last_seen == date(2026, 6, 5)
    assert found.next_due == date(2026, 7, 5)
    assert found.occurrences == 12
    assert found.confidence == D("1.00")
    assert not found.inflow


def test_biweekly_salary_is_income() -> None:
    payee = uuid.uuid4()
    found = only(
        detection.detect(rows(every(date(2026, 1, 2), 14), "2500.00", payee_id=payee), TODAY)
    )
    assert found.pattern is Pattern.BIWEEKLY
    assert (found.cadence, found.interval_count) == (Cadence.WEEKLY, 2)
    assert found.inflow
    assert found.payee_id == payee
    assert found.last_seen == date(2026, 6, 19)
    assert found.next_due == date(2026, 7, 3)


def test_weekly_quarterly_and_annual() -> None:
    weekly = rows(every(date(2026, 4, 3), 7), "-12.00", payee="Weekly Box")
    quarterly = rows(
        [add_months(date(2025, 1, 15), 3 * i) for i in range(6)], "-300.00", payee="Quarterly Tax"
    )
    annual = rows(
        [date(2023, 9, 1), date(2024, 9, 2), date(2025, 9, 1)], "-99.00", payee="Annual Domain"
    )
    found = {c.pattern: c for c in detection.detect(weekly + quarterly + annual, TODAY)}
    assert set(found) == {Pattern.WEEKLY, Pattern.QUARTERLY, Pattern.ANNUAL}
    assert found[Pattern.WEEKLY].next_due == date(2026, 7, 3)
    assert found[Pattern.QUARTERLY].cadence is Cadence.QUARTERLY
    assert found[Pattern.QUARTERLY].next_due == date(2026, 7, 15)
    assert found[Pattern.ANNUAL].cadence is Cadence.YEARLY
    assert found[Pattern.ANNUAL].next_due == date(2026, 9, 1)


def test_two_plans_with_one_payee_are_two_clusters() -> None:
    days = monthly(date(2026, 1, 10), 6)
    ledger = rows(days, "-9.99", payee="Cloud Store") + rows(
        [d + timedelta(days=3) for d in days], "-29.99", payee="Cloud Store"
    )
    found = detection.detect(ledger, TODAY)
    assert sorted(c.amount_min for c in found) == [D("-29.99"), D("-9.99")]
    assert all(c.pattern is Pattern.MONTHLY for c in found)


def test_variable_bill_is_found_with_lower_confidence() -> None:
    amounts = ["-80.00", "-95.00", "-110.00", "-70.00", "-100.00", "-85.00"]
    found = only(
        detection.detect(rows(monthly(date(2026, 1, 20), 6), amounts, payee="City Power"), TODAY)
    )
    assert found.pattern is Pattern.MONTHLY
    assert (found.amount_min, found.amount_max) == (D("-110.00"), D("-70.00"))
    # 0.5 * 1 + 0.3 * (1 - 40 / 90) + 0.2 * 1 = 0.8667 (median of the sizes: 90)
    assert found.confidence == D("0.87")
    assert found.confidence < D("1.00")


def test_jitter_within_tolerance_still_counts() -> None:
    rng = random.Random(7)
    days = [d + timedelta(days=rng.randint(-2, 2)) for d in monthly(date(2025, 10, 12), 9)]
    amounts = [D("-49.00") + D(rng.randint(0, 300)) / 100 for _ in days]
    found = only(detection.detect(rows(days, amounts, payee="Gym Club"), TODAY))
    assert found.pattern is Pattern.MONTHLY
    assert found.regularity == D("1.00")


def test_irregular_spending_is_not_recurring() -> None:
    day = date(2026, 1, 1)
    days = []
    for i in range(30):
        days.append(day)
        day += timedelta(days=2 if i % 2 else 11)
    assert detection.detect(rows(days, "-42.10", payee="Corner Grocer"), TODAY) == []


def test_too_few_occurrences_and_ended_patterns_are_dropped() -> None:
    two = rows(monthly(date(2026, 4, 1), 2), "-20.00", payee="Two Times")
    ended = rows(monthly(date(2025, 1, 1), 6), "-20.00", payee="Old Sub")
    assert detection.detect(two + ended, TODAY) == []


def test_overdue_next_due_moves_forward() -> None:
    # Last charge 2026-05-01; June's was missed but the pattern is recent.
    found = only(detection.detect(rows(monthly(date(2025, 11, 1), 7), "-5.00"), TODAY))
    assert found.last_seen == date(2026, 5, 1)
    assert found.next_due == date(2026, 7, 1)


def test_groups_split_by_account_and_direction() -> None:
    days = monthly(date(2026, 1, 3), 6)
    ledger = (
        rows(days, "-10.00", payee="Same Name")
        + rows(days, "-10.00", payee="Same Name", account=OTHER_ACCOUNT)
        + rows(days, "10.00", payee="Same Name")
    )
    found = detection.detect(ledger, TODAY)
    assert sorted((c.account_id == ACCOUNT, c.inflow) for c in found) == [
        (False, False),
        (True, False),
        (True, True),
    ]


def test_rows_without_payee_or_amount_are_ignored() -> None:
    days = monthly(date(2026, 1, 3), 6)
    ledger = rows(days, "-10.00", payee="") + rows(days, "0", payee="Zero")
    assert detection.detect(ledger, TODAY) == []


def test_category_is_the_most_common() -> None:
    food, other = uuid.uuid4(), uuid.uuid4()
    days = monthly(date(2026, 1, 3), 5)
    ledger = rows(days[:4], "-10.00", payee="Meal Kit", category=food) + rows(
        days[4:], "-10.00", payee="Meal Kit", category=other
    )
    assert only(detection.detect(ledger, TODAY)).category_id == food


def test_normalize_payee() -> None:
    assert detection.normalize_payee("  ACME*Store #123 ") == "acme store"
    assert detection.normalize_payee(None) == ""
    assert detection.normalize_payee("1234") == ""
